import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        final int N = 505;
        int[] blok = new int[N];
        int[] sum = new int[N];
        int[][] binom = new int[N][N];
        long[][] dp = new long[N][N];
        long[][] ways = new long[N][N];

        // Helper functions
        // Add mod
        class ModUtils {
            static void addMod(int[] a, int b) {
                a[0] += b;
                if (a[0] >= mod) a[0] -= mod;
            }

            static long mulMod(long a, long b) {
                return (a * b) % mod;
            }

            static long c2(int x) {
                return ((long) x * (x + 1) / 2) % mod;
            }
        }

        // Precompute binomial coefficients
        binom[0][0] = 1;
        for (int i = 1; i < N; ++i) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                binom[i][j] = (binom[i - 1][j] + binom[i - 1][j - 1]) % mod;
            }
        }

        // Calculate blok and sum arrays
        for (int x = 1; x <= m; ++x) {
            for (int i = 1; i <= x; ++i) {
                int[] temp1Arr = {0};
                ModUtils.addMod(temp1Arr, (int) ModUtils.mulMod(blok[i - 1], ModUtils.mulMod(blok[x - i], binom[x - 1][i - 1])));
                int temp1 = temp1Arr[0];
                ModUtils.addMod(blok, temp1);
                int[] temp2Arr = {0};
                long c2_i_1 = ModUtils.c2(i - 1);
                long c2_x_i = ModUtils.c2(x - i);
                ModUtils.addMod(temp2Arr, (int) ModUtils.mulMod(c2_i_1, c2_x_i));
                int temp2 = temp2Arr[0];
                ModUtils.addMod(sum, temp2);
                int[] temp3Arr = {0};
                long temp3Val = ModUtils.mulMod(sum[i - 1], ModUtils.mulMod(blok[x - i], binom[x - 1][i - 1]));
                ModUtils.addMod(temp3Arr, (int) temp3Val);
                int temp3 = temp3Arr[0];
                ModUtils.addMod(sum, temp3);
                int[] temp4Arr = {0};
                long temp4Val = ModUtils.mulMod(sum[x - i], ModUtils.mulMod(blok[i - 1], binom[x - 1][i - 1]));
                ModUtils.addMod(temp4Arr, (int) temp4Val);
                int temp4 = temp4Arr[0];
                ModUtils.addMod(sum, temp4);
            }
            // Multiply blok[x] by (x + 1)
            blok[x] = (blok[x] * (x + 1)) % mod;
        }

        ways[0][0] = 1;
        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= i; ++j) {
                for (int sz = 1; sz <= i; ++sz) {
                    int[] temp1Arr = {0};
                    long temp1Val = ModUtils.mulMod(ways[i - sz][j - 1], ModUtils.mulMod(blok[sz], binom[m - i + sz][sz]));
                    ModUtils.addMod(temp1Arr, (int) temp1Val);
                    int temp1 = temp1Arr[0];
                    ModUtils.addMod(ways[i], temp1);

                    int[] temp2Arr = {0};
                    long temp2Val = ModUtils.mulMod(ways[i - sz][j - 1], ModUtils.mulMod(sum[sz], binom[m - i + sz][sz]));
                    ModUtils.addMod(temp2Arr, (int) temp2Val);
                    int temp2 = temp2Arr[0];
                    ModUtils.addMod(dp[i], temp2);

                    int[] temp3Arr = {0};
                    long temp3Val = ModUtils.mulMod(dp[i - sz][j - 1], ModUtils.mulMod(blok[sz], binom[m - i + sz][sz]));
                    ModUtils.addMod(temp3Arr, (int) temp3Val);
                    int temp3 = temp3Arr[0];
                    ModUtils.addMod(dp[i], temp3);
                }
            }
        }

        int ans = 0;
        for (int i = 1; i <= m; ++i) {
            int zero = n - m;
            int lef = zero - (i - 1);
            if (lef >= 0) {
                int[] tempArr = {0};
                long tempVal = ModUtils.mulMod(dp[m][i], binom[i + lef][lef]);
                ModUtils.addMod(tempArr, (int) tempVal);
                int temp = tempArr[0];
                ModUtils.addMod(ans, temp);
            }
        }
        System.out.println(ans);
        sc.close();
    }
}
